36	// SplitTurns produces one Turn per user-prompt envelope, bounded by the next.
37	// Token usage is delegated to the Factory agent; spawned-subagent usage comes
38	// back as a cumulative snapshot and is rescoped to a per-turn delta by
39	// splitLineTurns (see rescopeSubagentTokensToDeltas). The model is read once
40	// from the session's adjacent settings file. Droid
41	// envelopes carry no per-message timestamp (the agent stamps events with
42	// time.Now() at hook time), so every turn falls back to the transcript file's
43	// modtime — the same fallback the Gemini importer uses.
44	func (factoryImporter) SplitTurns(sf SessionFile, full []byte) ([]Turn, error) {
45		subagentsDir := filepath.Join(filepath.Dir(sf.Path), sf.SessionID, "subagents")
46		model := factoryaidroid.ExtractModelFromTranscript(sf.Path)
47		var createdAt time.Time
48		if info, statErr := os.Stat(sf.Path); statErr == nil {
49			createdAt = info.ModTime()
50		}
51		ag := &factoryaidroid.FactoryAIDroidAgent{}
52		return splitLineTurns(splitRawLines(full),
53			func(raw []byte) bool { _, ok := factoryPromptText(raw); return ok },
54			func(rawLines [][]byte, start, _ int, truncated []byte) (*Turn, error) {
55				tokens, err := ag.CalculateTotalTokenUsage(truncated, start, subagentsDir)
56				if err != nil {
57					return nil, fmt.Errorf("token usage: %w", err)
58				}
59				var env struct {
60					ID string `json:"id"`
61				}
62				if err := json.Unmarshal(rawLines[start], &env); err != nil {
63					//nolint:nilerr // skip defensively; the line already parsed in factoryPromptText
64					return nil, nil
65				}
66				prompt, _ := factoryPromptText(rawLines[start])
67				return &Turn{UUID: env.ID, Prompt: prompt, Model: model, CreatedAt: createdAt, Tokens: tokens}, nil
68			})
69	}
