71	// factoryPromptText reports whether a raw Droid JSONL line is a user-prompt
72	// message and returns its text. Droid tags the role inside the inner message;
73	// tool_result user messages carry no extractable text and return false.
74	func factoryPromptText(raw []byte) (string, bool) {
75		var env struct {
76			Type    string          `json:"type"`
77			Message json.RawMessage `json:"message"`
78		}
79		if err := json.Unmarshal(raw, &env); err != nil || env.Type != "message" {
80			return "", false
81		}
82		var role struct {
83			Role string `json:"role"`
84		}
85		if err := json.Unmarshal(env.Message, &role); err != nil || role.Role != transcript.TypeUser {
86			return "", false
87		}
88		text := transcript.ExtractUserContent(env.Message)
89		if text == "" {
90			return "", false
91		}
92		return text, true
93	}
