export const meta = {
  name: 'harness-surface-atlas',
  description: 'Map instruction/rule/skill/command/persona surfaces across every AI coding harness, plus how openspec init handles breadth',
  phases: [
    { title: 'Survey', detail: 'one agent per harness family + openspec init' },
    { title: 'Verify', detail: 'adversarially check each claimed path' },
    { title: 'Synthesize', detail: 'capability matrix + adapter recommendation' },
  ],
}

const HARNESS_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['harnesses'],
  properties: {
    harnesses: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['name', 'instructionFiles', 'rulesDir', 'skills', 'commands', 'personas', 'userScope', 'confidence', 'evidence'],
        properties: {
          name: { type: 'string' },
          instructionFiles: {
            type: 'array',
            description: 'Project-scope always-on instruction files this harness reads, in precedence order. Empty if none.',
            items: { type: 'string' },
          },
          rulesDir: { type: 'string', description: 'Directory of separately-loaded rule files, with file extension, or empty string if none' },
          skills: { type: 'string', description: 'Path pattern for model-invoked skills, or empty string if the harness has no such concept' },
          commands: { type: 'string', description: 'Path pattern for user-invoked commands, or empty string if none' },
          personas: { type: 'string', description: 'Path pattern for delegated subagents, or empty string if none' },
          userScope: { type: 'string', description: 'Per-user home equivalent of the above, or empty string if none' },
          supportsImports: { type: 'string', description: 'Whether the instruction file supports including other files, and the syntax. Empty if unknown.' },
          confidence: { type: 'string', enum: ['verified-on-disk', 'official-docs', 'community-reported', 'uncertain'] },
          evidence: { type: 'string', description: 'Where this came from: file path on disk, doc URL, or repo path' },
        },
      },
    },
  },
}

const VERDICT_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['name', 'corrections', 'confirmed'],
  properties: {
    name: { type: 'string' },
    confirmed: { type: 'boolean', description: 'true if the surveyed paths hold up under checking' },
    corrections: { type: 'string', description: 'Any path, format or capability the survey got wrong, with the correct value and its source. Empty string if nothing to correct.' },
    deprecationRisk: { type: 'string', description: 'Whether any listed surface is legacy/deprecated in favor of a newer one. Empty if none.' },
  },
}

// Grouped so each agent has enough to chew on but stays focused.
const GROUPS = [
  { key: 'claude-codex', list: 'Claude Code, OpenAI Codex CLI' },
  { key: 'cursor-windsurf', list: 'Cursor, Windsurf' },
  { key: 'gemini-copilot', list: 'Gemini CLI, GitHub Copilot (both the CLI and the VS Code/JetBrains extension)' },
  { key: 'cline-roo-kilo', list: 'Cline, Roo Code, Kilo Code' },
  { key: 'aider-continue-goose', list: 'Aider, Continue, Goose' },
  { key: 'zed-amp-opencode', list: 'Zed, Amp (Sourcegraph), OpenCode' },
  { key: 'jetbrains-trae-warp', list: 'JetBrains Junie, Trae, Warp' },
  { key: 'factory-pi-augment', list: 'Factory AI Droid, Pi (earendil-works), Augment Code' },
]

phase('Survey')

log(`Surveying ${GROUPS.length} harness groups plus openspec init`)

// openspec init is the pattern the user explicitly asked us to follow — survey it alongside.
const openspecProbe = agent(
  `Determine exactly how \`openspec init\` handles multiple AI coding harnesses.

The openspec CLI is installed at C:\\Users\\brasp\\AppData\\Roaming\\npm\\node_modules\\@fission-ai\\openspec — read its source directly (dist/ is bundled JS; look for the init command and any harness/tool registry).

Answer precisely:
1. Which AI tools/harnesses does \`openspec init\` offer? Give the exact list of names as presented to the user.
2. For each, what file(s) does it create or modify, and at what path?
3. Is there a registry/table structure in the code, or is it a switch? Show the shape.
4. How does it handle a tool being already configured, and how does it update an existing file — full rewrite, or a marker-delimited managed block? If markers, quote them exactly.
5. Does it write into files the user also owns (like CLAUDE.md), and if so how does it avoid clobbering?

Quote real code. This is the pattern a new CLI has been asked to copy, so precision about the registry shape and the update strategy matters more than breadth.`,
  { label: 'openspec-init', phase: 'Survey' }
)

// Each group: survey then immediately verify, no barrier between groups.
const surveyed = await pipeline(
  GROUPS,
  (g) =>
    agent(
      `Map the configuration surfaces of these AI coding harnesses: ${g.list}.

For EACH harness, determine where it reads each of these five kinds of content from a PROJECT directory, and from the USER home:

1. **instruction** — always-on context loaded every session (e.g. a CLAUDE.md-style file)
2. **rule** — separately-loaded instruction files in a directory, often scopeable to file globs
3. **skill** — content the model itself decides to load based on a description
4. **command** — content the user triggers by typing an explicit token
5. **persona** — a delegated subagent with its own model/tool budget

Report the exact path pattern and file format for each. Use an empty string where the harness genuinely has no such concept — do NOT invent a plausible-looking path. Distinguish clearly between what you verified and what you are inferring.

Sources, in order of preference: (a) files actually present on this machine — check C:\\Users\\brasp\\ for dot-directories and C:\\Users\\brasp\\Documents\\GitHub\\cli which integrates with many of these; (b) official documentation via WebFetch/WebSearch; (c) community sources. Set the confidence field honestly per harness.

Also record whether the instruction file supports importing/including other files, and the exact syntax — this matters a great deal for the tool being designed.`,
      { label: `survey:${g.key}`, phase: 'Survey', schema: HARNESS_SCHEMA }
    ),
  (survey, g) =>
    survey
      ? parallel(
          survey.harnesses.map((h) => () =>
            agent(
              `Adversarially verify this claim about the AI coding harness "${h.name}".

Claimed surfaces:
- instruction files: ${JSON.stringify(h.instructionFiles)}
- rules dir: ${h.rulesDir || '(none)'}
- skills: ${h.skills || '(none)'}
- commands: ${h.commands || '(none)'}
- personas: ${h.personas || '(none)'}
- user scope: ${h.userScope || '(none)'}
- imports: ${h.supportsImports || '(unknown)'}
- stated confidence: ${h.confidence}, evidence: ${h.evidence}

Your job is to REFUTE these, not confirm them. Check the official docs and any on-disk evidence. Look specifically for: a path that was plausibly guessed rather than documented; a surface that is deprecated in favour of a newer one; a claimed "no such concept" that actually exists under a different name; and a path that is correct for a different product with a similar name.

Default to reporting a correction when you are unsure. Set confirmed=false if anything is wrong.`,
              { label: `verify:${h.name}`, phase: 'Verify', schema: VERDICT_SCHEMA }
            ).then((v) => ({ harness: h, verdict: v }))
          )
        )
      : []
)

const checked = surveyed.flat().filter(Boolean)
const openspec = await openspecProbe

log(`Surveyed ${checked.length} harnesses; ${checked.filter((c) => c.verdict && !c.verdict.confirmed).length} had corrections`)

phase('Synthesize')

const synthesis = await agent(
  `You are producing a capability matrix for a CLI called harnaas, which installs five kinds of asset into AI coding harnesses.

The five asset types are fixed and named: **skill** (model-invoked), **rule** (auto-loaded file, may be glob-scoped), **instruction** (always-on content in a committed memory file), **command** (user-invoked), **persona** (delegated subagent).

Here is the surveyed and adversarially-verified data. Where a verdict has corrections, TRUST THE CORRECTION over the original survey:

${JSON.stringify(checked, null, 1)}

And here is how \`openspec init\` — the pattern harnaas has been explicitly asked to follow for breadth — handles multiple harnesses:

${openspec}

Produce:

1. **A capability matrix**, one row per harness, five columns for the asset types, showing the destination path or "—". Sort by number of supported types, descending. Mark low-confidence cells.

2. **Which asset types are near-universal, and which are Claude-Code-mostly.** Be specific with counts.

3. **The adapter interface this implies.** harnaas has already decided on a self-registering adapter registry with a hand-written AST import-boundary test. Given this data, say what the adapter interface must actually expose — and critically, whether "unsupported" needs to be a first-class outcome (how many harness × type cells are empty?).

4. **How closely harnaas should follow openspec init's approach**, given openspec writes only ONE kind of thing (an instruction file) while harnaas writes five. Name the specific things worth copying and the specific things that do not transfer.

5. **The three highest-risk design traps** this data reveals — places where a naive adapter would silently produce a file no harness reads. Be concrete.

6. **Open questions a human must decide**, phrased as decisions, not research tasks. Maximum five, ranked by consequence.

Be concrete and cite paths. Do not pad.`,
  { label: 'synthesis', phase: 'Synthesize', effort: 'high' }
)

return { synthesis, harnessCount: checked.length, openspecInit: openspec }

